import logging
import numpy as np
from scipy import linalg as la

logger = logging.getLogger(__name__)


class Solver:
    """Fast principal matrix square root solver.

    Uses eigendecomposition for well-conditioned matrices (the common case),
    falling back to scipy's Schur-based sqrtm only when necessary.
    """

    def solve(self, problem, **kwargs):
        A = np.asarray(problem["matrix"], dtype=complex)
        n = A.shape[0]

        # For tiny matrices the sqrtm overhead is negligible
        if n <= 3:
            try:
                X, _ = la.sqrtm(A, disp=False)
                return {"sqrtm": {"X": X.tolist()}}
            except Exception as e:
                logger.error(f"sqrtm failed: {e}")
                return {"sqrtm": {"X": []}}

        # Fast path: eigendecomposition
        result = self._solve_eig(A, n)
        if result is not None:
            return result

        # Robust fallback: scipy's Schur-based sqrtm
        try:
            X, _ = la.sqrtm(A, disp=False)
            return {"sqrtm": {"X": X.tolist()}}
        except Exception as e:
            logger.error(f"sqrtm failed: {e}")
            return {"sqrtm": {"X": []}}

    @staticmethod
    def _solve_eig(A, n):
        """Compute sqrtm via eigendecomposition. Returns None if not viable."""
        try:
            # Detect Hermitian matrices — eigh is 5-10x faster than eig.
            # Cheap pre-check: diagonal must be real for a Hermitian matrix.
            if np.allclose(np.diag(A).imag, 0, atol=1e-10):
                is_herm = np.allclose(A, A.conj().T, rtol=1e-7, atol=1e-10)
            else:
                is_herm = False

            if is_herm:
                eigvals, eigvecs = la.eigh(A, check_finite=False, driver="evd")
                sqrt_ev = np.sqrt(eigvals.astype(complex))
                # X = V @ diag(sqrt_ev) @ V^H  (V is unitary for Hermitian A)
                X = (eigvecs * sqrt_ev) @ eigvecs.conj().T
            else:
                eigvals, eigvecs = la.eig(A, check_finite=False)
                # Bail out if the eigenvector matrix is too ill-conditioned
                if np.linalg.cond(eigvecs) > 1e10:
                    return None
                sqrt_ev = np.sqrt(eigvals)
                X = (eigvecs * sqrt_ev) @ la.inv(eigvecs, check_finite=False)

            # Verify X @ X = A
            if np.allclose(X @ X, A, rtol=1e-5, atol=1e-8):
                return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            pass
        return None

