import logging
import numpy as np
from scipy import linalg as la

logger = logging.getLogger(__name__)


class Solver:
    """Fast principal matrix square root solver.

    Uses Schur decomposition with a custom fast triangular sqrt
    for general matrices, and eigh for Hermitian matrices.
    Falls back to scipy's sqrtm only when numerically necessary.
    """

    def solve(self, problem, **kwargs):
        A = np.asarray(problem["matrix"], dtype=complex)
        n = A.shape[0]

        if n <= 3:
            try:
                X, _ = la.sqrtm(A, disp=False)
                return {"sqrtm": {"X": X.tolist()}}
            except Exception as e:
                logger.error(f"sqrtm failed: {e}")
                return {"sqrtm": {"X": []}}

        # Fast path for Hermitian matrices
        result = self._try_hermitian(A)
        if result is not None:
            return result

        # Fast path: Schur + custom triangular sqrt
        result = self._try_schur(A)
        if result is not None:
            return result

        # Robust fallback
        try:
            X, _ = la.sqrtm(A, disp=False)
            return {"sqrtm": {"X": X.tolist()}}
        except Exception as e:
            logger.error(f"sqrtm failed: {e}")
            return {"sqrtm": {"X": []}}

    @staticmethod
    def _try_hermitian(A):
        """eigh is 5-10x faster than general eig for Hermitian matrices."""
        if not np.allclose(np.diag(A).imag, 0, atol=1e-10):
            return None
        if not np.allclose(A, A.conj().T, rtol=1e-7, atol=1e-10):
            return None
        try:
            eigvals, eigvecs = la.eigh(A, check_finite=False, driver="evd")
            eigvals = np.where(eigvals < 0, 0, eigvals)
            sqrt_ev = np.sqrt(eigvals.astype(complex))
            X = (eigvecs * sqrt_ev) @ eigvecs.conj().T
            return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            return None

    @staticmethod
    def _try_schur(A):
        """Schur decomposition + custom fast triangular sqrt."""
        try:
            T, Z = la.schur(A, output="complex")
            R = Solver._sqrt_triu(T)
            if R is None:
                return None
            X = Z @ R @ Z.conj().T
            if np.allclose(X @ X, A, rtol=1e-5, atol=1e-8):
                return {"sqrtm": {"X": X.tolist()}}
        except Exception:
            pass
        return None

    @staticmethod
    def _sqrt_triu(T):
        """Compute principal sqrt of upper triangular T.

        Uses forward substitution. Returns None if the computation is
        numerically unstable (eigenvalues whose square roots sum to ~0).
        """
        n = T.shape[0]
        R = np.zeros((n, n), dtype=complex)
        rd = np.sqrt(np.diag(T))
        for i in range(n):
            R[i, i] = rd[i]

        for j in range(1, n):
            rjj = rd[j]
            # Process rows from j-1 down to 0
            for i in range(j - 1, -1, -1):
                rii = rd[i]
                denom = rii + rjj
                if abs(denom) < 1e-12:
                    return None
                R[i, j] = (T[i, j] - np.dot(R[i, i + 1 : j], R[i + 1 : j, j])) / denom

        return R

